      { title: "\u{1F4A7} \uC801\uC808\uD55C DBP \uD761\uC218\uB7C9", desc: "90~130 ml/100g \u2014 \uACFC\uB3C4\uD55C \uC624\uC77C \uD761\uC218 \uC5C6\uC774 \uC801\uC815 \uC218\uC900\uC758 \uAD6C\uC870\uC131 \uC720\uC9C0. \uACE0\uCDA9\uC804(high loading) \uBC30\uD569 \uC124\uACC4\uC5D0\uB3C4 \uC801\uC6A9 \uAC00\uB2A5", enTitle: "\u{1F4A7} Optimal DBP Absorption", jaTitle: "\u{1F4A7} \u9069\u5207\u306ADBP\u5438\u6CB9\u91CF", enDesc: "90\u2013130 ml/100g \u2014 maintains adequate structure without excessive oil absorption, applicable to high-loading formulations", jaDesc: "90~130 ml/100g \u2014 \u904E\u5EA6\u306A\u30AA\u30A4\u30EB\u5438\u53CE\u306A\u3057\u306B\u9069\u6B63\u306A\u30EC\u30D9\u30EB\u306E\u69CB\u9020\u6027\u3092\u7DAD\u6301\u3002\u9AD8\u5145\u586B(high loading)\u914D\u5408\u8A2D\u8A08\u306B\u3082\u9069\u7528\u53EF\u80FD" },
      { title: "\u2696\uFE0F \uC911\uC131 pH (6.5~7.5)", desc: "\uC0B0\uC131\uC774\uB098 \uC54C\uCE7C\uB9AC\uC131 \uC2E4\uB9AC\uCE74\uAC00 \uC720\uAE30 \uBC14\uC778\uB354\uB098 \uACE0\uBB34\uC758 \uAC00\uAD50 \uAD6C\uC870\uB97C \uC190\uC0C1\uC2DC\uD0A4\uB294 \uD604\uC0C1 \uBC29\uC9C0. \uACBD\uD654\uC81C, \uAC00\uAD50\uC81C, \uCD09\uB9E4\uC640\uC758 \uBD80\uBC18\uC751 \uCD5C\uC18C\uD654", enTitle: "\u2696\uFE0F Neutral pH (6.5\u20137.5)", jaTitle: "\u2696\uFE0F \u4E2D\u6027pH (6.5~7.5)", enDesc: "Prevents damage to crosslinking structures in organic binders and rubber caused by acidic or alkaline silica \u2014 minimizes side reactions with curing agents, crosslinkers, and catalysts", jaDesc: "\u9178\u6027\u3084\u30A2\u30EB\u30AB\u30EA\u6027\u306E\u30B7\u30EA\u30AB\u304C\u6709\u6A5F\u30D0\u30A4\u30F3\u30C0\u30FC\u3084\u30B4\u30E0\u306E\u67B6\u6A4B\u69CB\u9020\u3092\u640D\u50B7\u3059\u308B\u73FE\u8C61\u3092\u9632\u6B62\u3002\u786C\u5316\u5264\u3001\u67B6\u6A4B\u5264\u3001\u89E6\u5A92\u3068\u306E\u526F\u53CD\u5FDC\u3092\u6700\u5C0F\u5316" },
      { title: "\u2728 \uB6F0\uC5B4\uB09C \uBC31\uC0C9\uB3C4 (\u226595)", desc: "\uCD5C\uC885 \uC81C\uD488\uC758 \uC0C9\uC0C1\uC774\uB098 \uD22C\uBA85\uB3C4\uB97C \uD574\uCE58\uC9C0 \uC54A\uC74C. \uCC29\uC0C9\uC774\uB098 \uB3C4\uC7A5 \uACF5\uC815\uC5D0\uC11C \uBCA0\uC774\uC2A4 \uC7AC\uB8CC\uB85C \uD65C\uC6A9\uB3C4 \uB192\uC74C", enTitle: "\u2728 Outstanding Whiteness (\u226595)", jaTitle: "\u2728 \u512A\u308C\u305F\u767D\u8272\u5EA6 (\u226595)", enDesc: "Does not affect the color or transparency of finished products \u2014 highly usable as a base material in coloring and coating processes", jaDesc: "\u6700\u7D42\u88FD\u54C1\u306E\u8272\u5408\u3044\u3084\u900F\u660E\u5EA6\u3092\u640D\u306A\u308F\u306A\u3044\u3002\u7740\u8272\u3084\u5857\u88C5\u5DE5\u7A0B\u3067\u306E\u30D9\u30FC\u30B9\u6750\u6599\u3068\u3057\u3066\u306E\u6D3B\u7528\u5EA6\u304C\u9AD8\u3044" },
      { title: "\u{1F525} \uC6B0\uC218\uD55C \uC5F4\uC801 \uC548\uC815\uC131", desc: "1000\u2103 \uC18C\uC131 \uAC10\uB7C9 3~5%\uB85C \uACE0\uC628 \uACF5\uC815\uC5D0\uC11C\uB3C4 \uBB34\uAC8C \uBCC0\uD654\uB098 \uD718\uBC1C \uC131\uBD84 \uBC29\uCD9C\uC774 \uC801\uC74C. \uACE0\uC628 \uACBD\uD654, \uC0AC\uCD9C, \uC555\uCD9C \uACF5\uC815\uC5D0\uC11C\uB3C4 \uBB3C\uC131 \uC720\uC9C0", enTitle: "\u{1F525} Excellent Thermal Stability", jaTitle: "\u{1F525} \u512A\u308C\u305F\u71B1\u7684\u5B89\u5B9A\u6027", enDesc: "Ignition loss of only 3\u20135% at 1000\xB0C \u2014 minimal weight change or volatile release during high-temperature processes; properties maintained through hot curing, injection, and extrusion", jaDesc: "1000\u2103\u713C\u6210\u6E1B\u91CF3~5%\u3067\u3001\u9AD8\u6E29\u5DE5\u7A0B\u3067\u3082\u91CD\u91CF\u5909\u5316\u3084\u63EE\u767A\u6210\u5206\u306E\u653E\u51FA\u304C\u5C11\u306A\u3044\u3002\u9AD8\u6E29\u786C\u5316\u3001\u5C04\u51FA\u3001\u62BC\u51FA\u5DE5\u7A0B\u3067\u3082\u7269\u6027\u3092\u7DAD\u6301" }
