      { title: "\u{1F527} \uB9DE\uCDA4 \uC785\uB3C4 \uB300\uC751", desc: "\uACE0\uAC1D \uACF5\uC815\uC5D0 \uB530\uB77C D50 \uBC0F \uBD84\uD3EC \uCEE4\uC2A4\uD130\uB9C8\uC774\uC9D5 \uAC00\uB2A5", enTitle: "\u{1F527} Customizable PSD", jaTitle: "\u{1F527} \u30AB\u30B9\u30BF\u30E0\u7C92\u5EA6\u5BFE\u5FDC", enDesc: "D50 and distribution can be tailored to the customer's process", jaDesc: "\u9867\u5BA2\u306E\u5DE5\u7A0B\u306B\u5FDC\u3058\u3066D50\u304A\u3088\u3073\u5206\u5E03\u306E\u30AB\u30B9\u30BF\u30DE\u30A4\u30BA\u53EF\u80FD" }
